import functools
import inspect

def get_globals(call):
    if hasattr(call, '__globals__'):
        return call.__globals__
    if isinstance(call, functools.partial):
        return get_globals(call.func)
    if hasattr(call, '__func__'):
        return get_globals(call.__func__)
    if hasattr(call, '__call__'):
        return get_globals(call.__call__)
    return {}

def foo(a: int):
    pass

class CallableClass:
    def __call__(self, a: int):
        pass

p = functools.partial(foo, a=1)
c = CallableClass()

